import{c as e,Q as r,j as n,m as o}from"./chunks/framework.BqPkuuVc.js";const a="/assets/change-report-options.AirCQjWb.png",s="/assets/change-report-list.BF5UDVvh.png",i="/assets/change-report-apply-targets.CjI21ucD.png",y=JSON.parse('{"title":"Changes report","description":"","frontmatter":{},"headers":[],"relativePath":"user/after-the-event/changes-report.md","filePath":"user/after-the-event/changes-report.md"}'),h={name:"user/after-the-event/changes-report.md"};function d(g,t,l,c,p,u){return r(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="changes-report" tabindex="-1">Changes report <a class="header-anchor" href="#changes-report" aria-label="Permalink to &quot;Changes report&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers and entry-desk leads running a series, a carnival or back-to-back events.</p><p>What changed about people during an event, and how to carry those changes into the next event and the competitor registry.</p><h2 id="what-it-s-for" tabindex="-1">What it&#39;s for <a class="header-anchor" href="#what-it-s-for" aria-label="Permalink to &quot;What it&#39;s for&quot;">​</a></h2><p>During an event the desk changes things about people: a runner buys a new card, moves up a class, has their club corrected, or turns up and enters on the day. Those changes are wanted again at the next event. Without this report, someone has to remember them and type them in again.</p><p>The changes report reads the event&#39;s <a href="./../reference/audit-trail">audit trail</a> and lists the <strong>net</strong> change for each person: what each field was at the start, and what it ended up as. You can print it or export it, and you can push the changes you choose into:</p><ul><li><strong>future events</strong>: today&#39;s afternoon race, tomorrow&#39;s stage of a carnival, next week&#39;s club event;</li><li><strong>the <a href="./../reference/competitor-registry">competitor registry</a></strong>, so every future event starts with the new card number or club.</li></ul><p>Open it from <strong>Competitors → Actions → Changes report…</strong>.</p><h2 id="building-the-report" tabindex="-1">Building the report <a class="header-anchor" href="#building-the-report" aria-label="Permalink to &quot;Building the report&quot;">​</a></h2><p><img src="'+a+'" alt="The first step of the Changes report: the changes to report, and the &quot;Only changes after the event started&quot; switch"></p><ol><li><p>Under <strong>Changes to report</strong>, tick what you want listed:</p><table tabindex="0"><thead><tr><th>Change</th><th>What it lists</th></tr></thead><tbody><tr><td><strong>Card number</strong></td><td>A new or different card. <em>Ticked to begin with.</em></td></tr><tr><td><strong>Class</strong></td><td>A move to another class. <em>Ticked to begin with.</em></td></tr><tr><td><strong>Club</strong></td><td>A club added or corrected.</td></tr><tr><td><strong>Name</strong></td><td>A name corrected.</td></tr><tr><td><strong>Bib number</strong></td><td>A bib given or changed.</td></tr><tr><td><strong>Entered on the day</strong></td><td>Someone who wasn&#39;t in the event when it started. Their card, class and club are folded into this one row.</td></tr></tbody></table></li><li><p>Leave <strong>Only changes after the event started</strong> on to list just the race day. Turn it off to include changes made during setup as well.</p></li><li><p>Click <strong>Build report</strong>.</p></li></ol><h2 id="reading-the-report" tabindex="-1">Reading the report <a class="header-anchor" href="#reading-the-report" aria-label="Permalink to &quot;Reading the report&quot;">​</a></h2><p><img src="'+s+'" alt="The Changes report listing four people: a hire card, an entry on the day, a new card and a class change, each with its notes"></p><p>The report lists one row per person per kind of change, sorted by name. Click any column heading to sort by it instead. Each row shows the change <strong>From</strong> and <strong>To</strong>, the competitor&#39;s <strong>Notes</strong> (where the desk writes things like &quot;borrowed card, back Sunday&quot;), and when it <strong>Changed</strong>. A card from the hire pool is marked <strong>Hire card</strong>.</p><p>More columns are available from the column button at the top right: the person&#39;s <strong>Class</strong> and <strong>Club</strong>, <strong>First changed</strong>, <strong>Times</strong> (how often it changed), <strong>Source</strong> (console, entry desk, AI assistant), <strong>Computer</strong>, and <strong>Registry</strong> (how the person was matched in the competitor registry). <strong>External ID</strong> and <strong>ID provider</strong> are shown to begin with, because they&#39;re how the person is found again in another system.</p><p>What the report leaves out:</p><ul><li><strong>Round trips.</strong> A card changed and changed back isn&#39;t a change.</li><li><strong>Imports.</strong> Re-importing the entry list restates hundreds of classes at once; that&#39;s a file arriving, not a decision. Only changes someone <em>made</em> count: at the console, the entry desk or by an AI assistant.</li><li><strong>Anything Manager worked out itself</strong>, such as a result or a status.</li><li><strong>People removed from the event.</strong> There&#39;s nothing to carry forward.</li></ul><p>Reading the report is often the whole job. Click <strong>Done</strong> when you&#39;re finished.</p><h3 id="exporting-it" tabindex="-1">Exporting it <a class="header-anchor" href="#exporting-it" aria-label="Permalink to &quot;Exporting it&quot;">​</a></h3><p><strong>Actions</strong> offers <strong>Export PDF</strong>, <strong>Export CSV</strong> and <strong>Export JSON</strong>. All three export the <strong>ticked</strong> rows, in the order the table is showing. PDF and CSV include the columns you can see; JSON includes every field, for a program to read.</p><h2 id="applying-changes-to-future-events" tabindex="-1">Applying changes to future events <a class="header-anchor" href="#applying-changes-to-future-events" aria-label="Permalink to &quot;Applying changes to future events&quot;">​</a></h2><ol><li>Tick the rows you want to carry forward (<strong>Select all</strong> and <strong>Select none</strong> help).</li><li>Choose <strong>Actions → Apply to future events…</strong>.</li><li>Tick the events to apply them to, then click <strong>Apply</strong>.</li></ol><p><img src="'+i+'" alt="Apply to future events, listing two later days of the same carnival (ticked) and a Thursday club night (not ticked)"></p><p>The list only offers events that are <strong>today or within the next 14 days</strong> and <strong>haven&#39;t been started</strong>. Today counts, because a morning and an afternoon race on the same day is ordinary. &quot;Not started&quot; keeps any event that has run, or is running, from having its results rewritten. If the event is a stage of a multi-stage event, the other stages come first and are already ticked. Nothing else is ticked for you.</p><p>Afterwards Manager lists every row for every event, including the ones it didn&#39;t write, with the reason:</p><table tabindex="0"><thead><tr><th>Result</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Applied</strong></td><td>Written.</td></tr><tr><td><strong>Already had it</strong></td><td>The event already held the new value. Applying twice does no harm.</td></tr><tr><td><strong>Overwrote a later change</strong></td><td>Someone had changed this field in that event since. The change was written anyway, and the row shows the value it replaced. These are worth a word with the other desk.</td></tr><tr><td><strong>Not entered</strong></td><td>The person isn&#39;t entered in that event. Manager never enters people for you.</td></tr><tr><td><strong>More than one match</strong></td><td>Two people in that event share this person&#39;s name and club. Manager won&#39;t guess which one is meant; make the change by hand.</td></tr><tr><td><strong>No class or club of that name</strong></td><td>The event has no class or club with that name, so nothing was written. Manager doesn&#39;t create one.</td></tr><tr><td><strong>Does not apply</strong></td><td>Not something that can be applied to an event, such as an &quot;Entered on the day&quot; row.</td></tr><tr><td><strong>Event cannot be changed</strong></td><td>The event has started, has passed, or is more than 14 days away.</td></tr><tr><td><strong>Could not be saved</strong></td><td>The write failed. This is the one result that leaves you something to do: check the event and try again.</td></tr></tbody></table><p>People are matched by their registration number, then their IOF ID, then their name and club, <strong>never by card number</strong>, because the card number is often the thing that changed. Each change is recorded in the target event&#39;s own audit trail with the source <strong>Changes report</strong>.</p><h2 id="applying-changes-to-the-competitor-registry" tabindex="-1">Applying changes to the competitor registry <a class="header-anchor" href="#applying-changes-to-the-competitor-registry" aria-label="Permalink to &quot;Applying changes to the competitor registry&quot;">​</a></h2><p><strong>Actions → Apply to competitor registry…</strong> saves the ticked changes against the people themselves, so every future event starts with them. Only card numbers, clubs and name corrections are saved:</p><ul><li><strong>A hire card is never saved</strong> (<strong>Hire card, not saved</strong>). It&#39;s the club&#39;s card, not the runner&#39;s, and saving it would make it theirs at every future event.</li><li><strong>A class or bib number belongs to one event</strong>, not to a person (<strong>Does not apply</strong>).</li><li><strong>Someone not in the registry, or matching more than one entry</strong>, is left alone (<strong>Not in the registry</strong>).</li><li><strong>A registry entry that has changed since</strong> is never overwritten (<strong>Changed since</strong>). An event keeps a record of what it used to hold; the registry doesn&#39;t, so an overwrite there couldn&#39;t be looked back at.</li></ul><p>The registry has no audit trail, so the report you exported is the only record of what was pushed. Export it first if you&#39;ll want to know later.</p><p>Applying to events and applying to the registry are separate actions on purpose, so a change meant for tomorrow&#39;s race never reaches the registry by accident. The ticked rows stay ticked after either one, so doing both is two passes over the same selection.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../reference/audit-trail">Audit trail</a> — where the report&#39;s changes come from</li><li><a href="./../reference/competitor-registry">Competitor registry</a></li><li><a href="./../event-setup/multi-stage-events">Multi-stage events</a></li><li><a href="./../event-setup/competitors-clubs-teams">Competitors, clubs and teams</a></li><li><a href="./end-of-event-checklist">End-of-event checklist</a></li></ul>',34)])])}const f=e(h,[["render",d]]);export{y as __pageData,f as default};
